function setView(name){market.hidden=name!=="markets";journal.hidden=name!=="journal";$("aiView").hidden=name!=="ai";$("researchView").hidden=name!=="research";$("profileView").hidden=name!=="profile";$("historyView").hidden=name!=="history";$("newsView").hidden=name!=="news";[ $("showDashboard"),chartsButton].forEach(b=>b.setAttribute("aria-selected","false"));const active={markets:$("showDashboard"),history:chartsButton}[name];if(active)active.setAttribute("aria-selected","true");if($("mpDrawer"))$("mpDrawer").hidden=true;window.scrollTo({top:0,behavior:"smooth"});}
