const profileKey="marketpilot-profile-v1";function getProfile(){try{return JSON.parse(localStorage.getItem(profileKey)||"{}")}catch(e){return {}}}function loadProfile(){const p=getProfile();$("mpName").value=p.name||"";$("mpLevel").value=p.level||"beginner";$("mpFocus").value=p.focus||"crypto";$("mpLanguage").value=p.language||"English";$("mpProfileTitle").textContent=p.name||"Local workspace";}$("mpSaveProfile").addEventListener("click",()=>{const p={name:$("mpName").value.trim(),level:$("mpLevel").value,focus:$("mpFocus").value,language:$("mpLanguage").value,savedAt:new Date().toISOString()};localStorage.setItem(profileKey,JSON.stringify(p));$("mpProfileTitle").textContent=p.name||"Local workspace";$("mpProfileStatus").textContent="Preferences saved on this device. No account has been created.";});$("mpExport").addEventListener("click",()=>{const blob=new Blob([JSON.stringify({app:"MarketPilot",exportedAt:new Date().toISOString(),profile:getProfile()},null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="marketpilot-preferences.json";a.click();URL.revokeObjectURL(url);});loadProfile();$("mpBackend").textContent=API_BASE?"MarketPilot AI endpoint configured":"MarketPilot AI URL missing";$("mpDate").textContent=new Date().toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"});
function renderAnswer(container,value){container.classList.add("mp-answer-block");let source=String(value||"").replace(/\r/g,"").trim();if(/^\s*\{/.test(source)){try{const parsed=JSON.parse(source);source=parsed?.choices?.[0]?.message?.content||parsed?.answer||parsed?.response||source;}catch(_){}}const lines=source.replace(/^#{1,6}(?=\S)/gm,"# ").split("\n");let list=null,listType="";for(const raw of lines){const line=raw.trim();if(!line){list=null;listType="";continue;}const heading=line.match(/^#{1,3}\s*(.+)/);if(heading){list=null;const h=document.createElement("h3");h.textContent=heading[1].replace(/\*\*/g,"");container.appendChild(h);continue;}const bullet=line.match(/^(?:[-*•])\s+(.+)/)||line.match(/^\d+[.)]\s+(.+)/);if(bullet){const type=/^\d/.test(line)?"ol":"ul";if(!list||listType!==type){list=document.createElement(type);listType=type;container.appendChild(list);}const li=document.createElement("li");li.textContent=bullet[1].replace(/\*\*/g,"");list.appendChild(li);continue;}list=null;listType="";const p=document.createElement("p");const parts=line.split(/(\*\*[^*]+\*\*)/g);parts.forEach(part=>{if(part.startsWith("**")&&part.endsWith("**")){const strong=document.createElement("strong");strong.textContent=part.slice(2,-2);p.appendChild(strong);}else p.appendChild(document.createTextNode(part));});container.appendChild(p);}}
function addMessage(role,text){const el=document.createElement("div");el.className="mp-message "+role;const label=document.createElement("small");label.textContent=role==="user"?"YOU":"FINANCIAL ASSISTANT";const body=document.createElement("div");if(role==="assistant")renderAnswer(body,text);else body.textContent=text;el.append(label,body);$("mpMessages").appendChild(el);$("mpMessages").scrollTop=$("mpMessages").scrollHeight;return el;}$("mpClearChat").addEventListener("click",()=>{if(!confirm("Clear this conversation? Your saved journal entries will remain unchanged."))return;$("mpMessages").innerHTML='<div class="mp-message assistant"><small>FINANCIAL ASSISTANT</small><div>New conversation. Ask a market question to begin.</div></div>';$("mpChatState").textContent="Ready";$("mpChatStatus").textContent="";});
async function getMacro(){try{const r=await fetch(MARKET_API,{cache:"no-store"});if(!r.ok)throw new Error("HTTP "+r.status);const d=await r.json();return {provider:d.provider||"FRED",fetchedAt:d.fetchedAt||null,data:d.data||{}};}catch(e){return {error:e.message,data:{}};}}
const symbols=[["BTC-USD","Bitcoin","BTC"],["ETH-USD","Ethereum","ETH"],["SOL-USD","Solana","SOL"],["BNB-USD","BNB","BNB"],["XRP-USD","XRP","XRP"]];let lastAssets=[],assetLoadPromise=null;
async function fetchAssets(){if(assetLoadPromise)return assetLoadPromise;assetLoadPromise=(async()=>{const response=await fetch(API_BASE+"/api/markets?group=crypto",{cache:"no-store"});const data=await response.json().catch(()=>({error:"Invalid crypto quote response"}));if(!response.ok)throw new Error(data.detail||data.error||"Crypto quotes unavailable (HTTP "+response.status+")");const bySymbol=new Map((data.assets||[]).map(item=>[item.symbol,item]));return symbols.map(([symbol,name,short])=>{const item=bySymbol.get(symbol);return item?{...item,source:item.source||"CoinPaprika",fetchedAt:item.fetchedAt||item.asOf||data.asOf||new Date().toISOString()}:{symbol,name,short,error:"Quote unavailable"};});
})();try{return await assetLoadPromise;}finally{assetLoadPromise=null;}}
function usd(n){if(!Number.isFinite(n))return "—";return "$"+n.toLocaleString("en-US",{maximumFractionDigits:n<1?5:2});}
function renderAssets(items){const host=$("mpAssets");host.replaceChildren();items.forEach(a=>{const row=document.createElement("div");row.className="mp-asset";const sym=document.createElement("div");sym.className="mp-symbol";sym.textContent=a.short;const middle=document.createElement("div");middle.className="mp-asset-main";const name=document.createElement("div");name.className="mp-asset-name";name.textContent=a.name;const note=document.createElement("div");note.className="mp-asset-note";note.textContent=a.error?"Unavailable: "+a.error:"24h market volume "+usd(a.volume)+" · updated "+(a.asOf?new Date(a.asOf).toLocaleTimeString():"time unavailable");middle.append(name,note);const right=document.createElement("div");right.className="mp-asset-price";const price=document.createElement("div");price.textContent=usd(a.price);const change=document.createElement("div");change.className="mp-asset-note "+(a.change>0?"mp-up":a.change<0?"mp-down":"");change.textContent=Number.isFinite(a.change)?(a.change>0?"+":"")+a.change.toFixed(2)+"% · 24h":"No quote";right.append(price,change);row.append(sym,middle,right);host.append(row);});const foot=document.createElement("p");foot.className="mp-status";foot.textContent="Source: CoinPaprika with Binance spot fallback · refreshed "+new Date().toLocaleTimeString()+" · aggregated USD quotes may be delayed.";host.append(foot);const promptHost=$("mpAssetPrompts");if(promptHost){promptHost.replaceChildren();const ranked=items.filter(x=>!x.error&&Number.isFinite(x.volume)).sort((a,b)=>b.volume-a.volume).slice(0,3);if(ranked.length){const heading=document.createElement("div");heading.className="mp-title";heading.textContent="Follow-ups · highest 24h quote volume";promptHost.appendChild(heading);const wrap=document.createElement("div");wrap.className="mp-prompts";ranked.forEach(a=>{const b=document.createElement("button");b.type="button";b.className="mp-prompt";b.textContent="Analyze "+a.short+" · "+usd(a.volume);b.addEventListener("click",()=>{ $("mpQuestion").value="Analyze "+a.name+" ("+a.symbol+") using the latest price, 24-hour change and quote volume. Explain plausible drivers only when supported by available data, give bull and bear scenarios, and list invalidation conditions. State source and timestamp; do not invent news.";setView("ai");$("mpQuestion").focus();});wrap.appendChild(b);});promptHost.appendChild(wrap);}}}
let crossAssetData={};const groupLabels={stocks:"US indices",forex:"Forex",commodities:"Commodities"};
function money(value,currency){if(!Number.isFinite(Number(value)))return "Quote unavailable";const n=Number(value);return (currency==="USD"?"$":currency==="JPY"?"¥":currency==="GBP"?"£":currency==="EUR"?"€":"")+n.toLocaleString("en-US",{maximumFractionDigits:n<1?5:2});}
function renderCrossCards(hostId,group,items,sourceLabel,append=false){const host=$(hostId);if(!host)return;if(!append)host.replaceChildren();const heading=document.createElement("div");heading.className="mp-market-section-title";heading.textContent=group==="crypto"?"CRYPTO · SPOT MARKETS":(groupLabels[group]||group).toUpperCase();host.appendChild(heading);items.forEach(item=>{const b=document.createElement("button");b.type="button";b.className="mp-cross-card";const left=document.createElement("div"),name=document.createElement("div"),sym=document.createElement("div");name.className="mp-cross-name";name.textContent=item.name||item.short||item.symbol;sym.className="mp-cross-symbol";sym.textContent=item.symbol||item.short||"";left.append(name,sym);const right=document.createElement("div"),price=document.createElement("div"),change=document.createElement("div");right.className="mp-cross-right";price.textContent=item.error?"Unavailable":money(item.price,item.currency||"USD");change.className="mp-cross-change "+(Number(item.change)>0?"mp-up":Number(item.change)<0?"mp-down":"");if(group==="forex"&&Number.isFinite(Number(item.price)))price.textContent=Number(item.price).toLocaleString("en-US",{maximumFractionDigits:5});change.textContent=Number.isFinite(Number(item.change))?(Number(item.change)>0?"+":"")+Number(item.change).toFixed(2)+"%":"Quote unavailable";right.append(price,change);b.append(left,right);b.addEventListener("click",()=>{$("mpQuestion").value="Analyze "+(item.name||item.symbol)+" using the latest available quote, recent percentage change, macro context and risk scenarios. Separate observed data from interpretation, cite the data source and timestamp if supplied, and do not invent news or price levels.";setView("ai");$("mpQuestion").focus();});host.appendChild(b);});const foot=document.createElement("div");foot.className="mp-cross-foot";foot.textContent=sourceLabel||"Quotes may be delayed. Verify provider and exchange before trading.";host.appendChild(foot);}
async function fetchCrossAssetGroup(group){const response=await fetch(API_BASE+"/api/markets?group="+encodeURIComponent(group),{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Market quote request failed");crossAssetData[group]=data;return data;}
async function showMarketGroup(group,hostId="mpCrossAssetPanel"){const tabs=$("mpMarketTabs");if(tabs)tabs.querySelectorAll("[data-group]").forEach(b=>b.classList.toggle("active",b.dataset.group===group));const host=$(hostId);if(!host)return;if(group==="crypto"){if(!lastAssets.length){host.textContent="Loading crypto quotes…";try{lastAssets=await fetchAssets();}catch(e){host.textContent="Crypto quotes unavailable: "+e.message;return;}}renderCrossCards(hostId,"crypto",lastAssets,"Source: CoinPaprika with Binance spot fallback · refreshed "+new Date().toLocaleTimeString()+" · aggregated USD quotes may be delayed.");return;}host.textContent="Loading "+(groupLabels[group]||group)+" quotes…";try{const data=crossAssetData[group]||await fetchCrossAssetGroup(group);renderCrossCards(hostId,group,data.assets||[],"Source: Yahoo Finance chart endpoint · snapshot "+new Date(data.asOf||Date.now()).toLocaleString()+" · quotes may be delayed.");}catch(e){host.textContent="Could not load "+(groupLabels[group]||group)+": "+e.message;}}
async function refreshAllCrossAsset(){const host=$("mpResearchCrossAsset");if(host)host.replaceChildren();const groups=["stocks","forex","commodities"];await Promise.all(groups.map(async group=>{try{const data=await fetchCrossAssetGroup(group);renderCrossCards("mpResearchCrossAsset",group,data.assets||[],"Source: Yahoo Finance chart endpoint · snapshot "+new Date(data.asOf||Date.now()).toLocaleString()+" · quotes may be delayed.",true);}catch(e){}}));}
async function getAllCrossAssetData(){const groups=["stocks","forex","commodities"];await Promise.all(groups.map(async group=>{if(!crossAssetData[group]){try{await fetchCrossAssetGroup(group);}catch(e){crossAssetData[group]={group,assets:[],error:e.message};}}}));return crossAssetData;}
$("mpMarketTabs")?.querySelectorAll("[data-group]").forEach(button=>button.addEventListener("click",()=>showMarketGroup(button.dataset.group)));
async function refreshAssets(){ $("mpRefresh").disabled=true;$("mpResearchStatus").textContent="Fetching current public crypto prices…";try{lastAssets=await fetchAssets();renderAssets(lastAssets);await refreshAllCrossAsset();$("mpResearchStatus").textContent="Fetched "+lastAssets.filter(a=>!a.error).length+" crypto quotes and refreshed cross-asset markets at "+new Date().toLocaleTimeString()+".";}catch(e){$("mpResearchStatus").textContent="Refresh failed: "+e.message;}finally{$("mpRefresh").disabled=false;}}
$("mpRefresh").addEventListener("click",refreshAssets);
async function callBackend(path,payload){if(!API_BASE)throw new Error("MarketPilot AI service URL is not configured. Set MARKETPILOT_API_BASE in the public frontend configuration.");const r=await fetch(API_BASE+path,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const d=await r.json().catch(()=>({detail:"Invalid response from AI service"}));if(!r.ok)throw new Error(d.detail||d.error||"AI request failed (HTTP "+r.status+")");return d;}
